package remove_dep

import (
	"github.com/MateusMoutinhoOrg/Agnos/sandbox/api"
)

// NewCommand builds this command's declaration — the whole of what its
// entries.yaml says — and closes CommandHandler over the sandbox as the
// handler behind it. It is called once, by sandbox/binds/cli.go, and what it
// returns is one entry of sandbox.Commands.
// Generated by `agnos build` — do not edit by hand; the logic
// lives in handler.go.
func NewCommand(sandbox *api.Sandbox) *api.Command {
	command := api.NewCommand()

	command.Name = "remove_dep"
	command.Identifiers = []string{"remove-dep"}
	command.Category = "Deps System"
	command.Help = "Uninstalls one dep from the project"
	command.LongDescription = "Removes every adapter whose declaration names the dep, its require and its enrollment in every available, then the contract itself, then calls build."
	command.Examples = []string{"remove-dep embeddeps", "remove-dep embeddeps --path ./my-project"}
	command.Hidden = false

	command.Flags = []api.CommandFlag{
		{
			Id:          "with-adapters",
			Type:        "boolean",
			Required:    false,
			Array:       false,
			Description: "also remove every adapter that fills the dep (without it, a dep with adapters installed is refused)",
			Examples:    []string{"remove-dep serverdeps --with-adapters"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--with-adapters"},
		},
		{
			Id:          "path",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "the dir holding the project (defaults to the current directory)",
			Examples:    []string{"remove-dep --path ./my-project"},
			Default:     ".",
			HasDefault:  true,
			Identifiers: []string{"--path"},
		},
		{
			Id:          "quiet",
			Type:        "boolean",
			Required:    false,
			Array:       false,
			Description: "Quiets the cli output",
			Examples:    []string{"remove-dep embeddeps -q"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--quiet", "-q"},
		},
	}

	command.Args = []api.CommandArg{
		{
			Id:          "dep",
			Type:        "string",
			Required:    true,
			Array:       false,
			Description: "the dep to remove from the project",
			Examples:    []string{"remove-dep embeddeps"},
			Default:     "",
			HasDefault:  false,
		},
	}

	command.Handler = func() int {
		return CommandHandler(sandbox, command)
	}

	return command
}
